  yellow: '\x1b[33m',
  red: '\x1b[31m',
  magenta: '\x1b[35m',
  white: '\x1b[37m',
  gray: '\x1b[90m',
};

function c(color: string, text: string): string {
  return `${color}${text}${COLORS.reset}`;
}

