      const r = await dm.restart();
      console.log(r.success ? `? ${r.message}` : `? ${r.message}`);
      process.exit(r.success ? 0 : 1);
      break;
    }
    case 'status': {
      const status = await dm.status();
      if (status.running) {
        const uptime = dm.formatUptime(status.uptime!);
        console.log(
          `?? ???  PID: ${status.state!.pid}  ??: ${status.state!.port}  ??: ${uptime}${status.memoryUsage ? `  ??: ${status.memoryUsage}` : ''}`
        );
      } else {
        console.log('?? ???');
      }
      process.exit(status.running ? 0 : 1);
      break;
    }
    case 'logs': {
      const n = parseInt(args[1], 10) || 30;
      const logText = await dm.logs(n);
      console.log(logText);
      process.exit(0);
      break;
    }
    default:
      console.log(`??: npm run cli daemon <start|stop|restart|status|logs>`);
      process.exit(1);
  }
}

