  /**
   * ??????
   * @param error - ????
   * @returns ????
   */
  private classifyError(error: string): 'retryable' | 'non_retryable' {
    const retryablePatterns = /timeout|network|ECONNREFUSED|ETIMEDOUT|503|429/i;
    const nonRetryablePatterns =
      /permission|auth|invalid.?param|not.?found|??|??|????|???/i;
    if (nonRetryablePatterns.test(error)) return 'non_retryable';
    if (retryablePatterns.test(error)) return 'retryable';
    return 'non_retryable';
  }

  /**
   * ????????
   * @param toolName - ????
   * @param args - ????
   * @param context - ?????
   * @param maxRetries - ??????
   * @returns ??????
   */
  private async executeWithRetry(
    toolName: string,
    args: Record<string, unknown>,
    context: ToolContext,
    maxRetries: number = 2
  ): Promise<ToolResult> {
    let lastResult: ToolResult | null = null;
    let retryCount = 0;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const result = await Promise.race([
          this.deps.toolRegistry.execute(toolName, args, context),
          this.createTimeoutPromise(TOOL_TIMEOUT_MS, toolName),
        ]);

        if (result.success) {
          if (retryCount > 0) {
            result.metadata = { ...result.metadata, retryCount };
          }
          return result;
        }

        lastResult = result;
        const errorType = this.classifyError(result.error || '');

        if (errorType === 'non_retryable' || attempt >= maxRetries) {
          if (result.metadata) {
            result.metadata.retryCount = retryCount;
          } else {
            result.metadata = { retryCount };
          }
          return result;
        }

        retryCount++;
        Logger.info(
          `?? ?? ${toolName} ????(?????)??${retryCount}???...`,
          'Executor'
        );
        await new Promise((resolve) => setTimeout(resolve, 500 * retryCount));
      } catch (err) {
        const errorMessage = (err as Error).message;
        const errorType = this.classifyError(errorMessage);

        lastResult = {
          success: false,
          output: null,
          error: errorMessage,
          duration: 0,
          validated: false,
          metadata: { retryCount },
        };

        if (errorType === 'non_retryable' || attempt >= maxRetries) {
          return lastResult;
        }

        retryCount++;
        Logger.info(
          `?? ?? ${toolName} ????(?????)??${retryCount}???...`,
          'Executor'
        );
        await new Promise((resolve) => setTimeout(resolve, 500 * retryCount));
      }
    }

    return (
      lastResult || {
        success: false,
        output: null,
        error: '?????????????',
        duration: 0,
        validated: false,
        metadata: { retryCount },
      }
    );
  }

