  /** toOpenAITools() ?? */
  private cachedOpenAITools: OpenAIToolDef[] | null = null;

  /**
   * ????
   */
  register(
    definition: ToolDefinition,
    execute: (
      params: Record<string, unknown>,
      context: ToolContext
    ) => Promise<ToolResult>
  ): void {
    if (this.tools.has(definition.name)) {
      Logger.debug(
