      'ToolRegistry'
    );
  }

  /**
   * ????
   */
  unregister(name: string): boolean {
    const removed = this.tools.delete(name);
    if (removed) {
      this.cachedOpenAITools = null;
      Logger.info(`?? ????: ${name}`, 'ToolRegistry');
    }
    return removed;
  }

  /**
   * ???????
   */
  get(name: string): RegisteredTool | undefined {
