    return this.tools.size;
  }

  /**
   * ??????
   */
  async execute(
    name: string,
    params: Record<string, unknown>,
    context: ToolContext
  ): Promise<ToolResult> {
    const tool = this.tools.get(name);
    if (!tool) {
      return {
        success: false,
        output: null,
        error: `?????: ${name}`,
        duration: 0,
        validated: false,
      };
    }

    const startTime = Date.now();
    try {
      Logger.info(
        `?? ????: ${name} | ??=${tool.definition.riskLevel}`,
        'ToolRegistry'
      );

      // ????
      const result = await perf.measure(
        `tool.${name}`,
        () =>
          Promise.race([
            tool.execute(params, context),
            this.createTimeoutPromise(tool.definition.timeout, name),
          ]),
        'tool'
      );

      const finalResult: ToolResult = {
        ...result,
        duration: Date.now() - startTime,
        validated: result.validated ?? false,
      };

      this.reliabilityTracker.recordCall(
        name,
        finalResult.success,
        finalResult.duration,
        finalResult.error
      );

      return finalResult;
    } catch (err) {
      const errorResult: ToolResult = {
        success: false,
        output: null,
        error: (err as Error).message,
        duration: Date.now() - startTime,
        validated: false,
      };

      this.reliabilityTracker.recordCall(
        name,
        false,
        errorResult.duration,
        errorResult.error
      );

      return errorResult;
    }
  }

  /**
   * ?? LLM ??? tool call
   */
  async executeToolCall(
    toolCall: {
      id: string;
      type: string;
      function: { name: string; arguments: string };
    },
    context: ToolContext
  ): Promise<ToolResult> {
    const toolName = toolCall.function.name;
    let args: Record<string, unknown> = {};
    try {
      args = JSON.parse(toolCall.function.arguments);
    } catch {
      args = {};
    }

    return this.execute(toolName, args, context);
  }

  /**
   * ??? OpenAI Function Calling ????
   * ???????????????? ? ???????????? description
   */
  toOpenAITools(): OpenAIToolDef[] {
    if (this.cachedOpenAITools) return this.cachedOpenAITools;

    const tools: OpenAIToolDef[] = [];

    const categoryOrder: ToolCategory[] = [
      ToolCategory.COGNITION,
      ToolCategory.MEMORY,
      ToolCategory.DAILY,
      ToolCategory.NETWORK,
      ToolCategory.SYSTEM,
      ToolCategory.FILE,
      ToolCategory.CODE,
      ToolCategory.DESKTOP,
    ];

    const sorted = Array.from(this.tools.values()).sort((a, b) => {
      const ai = categoryOrder.indexOf(a.definition.category);
      const bi = categoryOrder.indexOf(b.definition.category);
      if (ai !== bi) return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);

      const scoreA = this.reliabilityTracker.getCompositeScore(
        a.definition.name
      );
      const scoreB = this.reliabilityTracker.getCompositeScore(
        b.definition.name
      );
      return scoreB - scoreA;
    });

    const avgCompositeScore =
      sorted.length > 0
        ? sorted.reduce(
            (sum, t) =>
              sum +
              this.reliabilityTracker.getCompositeScore(t.definition.name),
            0
          ) / sorted.length
        : 1.0;

    for (const tool of sorted) {
      const properties: Record<string, unknown> = {};
      for (const [paramName, paramDef] of Object.entries(
        tool.definition.parameters
      )) {
        properties[paramName] = this.parameterDefToOpenAI(paramDef);
      }

      const compositeScore = this.reliabilityTracker.getCompositeScore(
        tool.definition.name
      );
      const evolutionWeight = this.reliabilityTracker.getEvolutionWeight(
        tool.definition.name
      );
      let description = tool.definition.description;

      if (evolutionWeight !== 1.0 || compositeScore < avgCompositeScore * 0.8) {
        if (evolutionWeight > 1.0) {
          description += ` [??:????${evolutionWeight.toFixed(2)}]`;
        } else if (evolutionWeight < 1.0) {
          description += ` [??:????${evolutionWeight.toFixed(2)}]`;
        }
        if (compositeScore < 0.5) {
          description += ` [????:${(compositeScore * 100).toFixed(0)}%]`;
        }
      }

      tools.push({
        type: 'function',
        function: {
          name: tool.definition.name,
          description,
          parameters: {
            type: 'object',
            properties,
            required: tool.definition.requiredParams,
          },
        },
      });
    }

    this.cachedOpenAITools = tools;
    return tools;
  }

  /**
   * ? ToolParameterDef ??? OpenAI Schema ??
   */
  private parameterDefToOpenAI(
    param: ToolParameterDef
  ): Record<string, unknown> {
    const schema: Record<string, unknown> = {
      type: param.type,
      description: param.description,
    };

    if (param.enum) {
      schema.enum = param.enum;
    }

    if (param.default !== undefined) {
      schema.default = param.default;
    }

    if (param.type === 'array' && param.items) {
      schema.items = this.parameterDefToOpenAI(param.items);
    }

    if (param.type === 'object' && param.properties) {
      const props: Record<string, unknown> = {};
      for (const [key, val] of Object.entries(param.properties)) {
        props[key] = this.parameterDefToOpenAI(val);
      }
      schema.properties = props;
    }

    return schema;
  }

  /**
   * ???? Promise
   */
  private createTimeoutPromise(
    timeoutMs: number,
    toolName: string
  ): Promise<never> {
    return new Promise((_, reject) => {
      setTimeout(() => {
        reject(new Error(`??????: ${toolName} (${timeoutMs}ms)`));
      }, timeoutMs);
    });
  }

  /**
   * ???????/???????????????
   */
  invalidateCache(): void {
    this.cachedOpenAITools = null;
  }

  private reliabilityTracker = new ToolReliabilityTracker();

  /**
   * ??????????
   */
  getReliabilityTracker(): ToolReliabilityTracker {
    return this.reliabilityTracker;
  }
}

export class ToolReliabilityTracker {
  private stats: Map<
    string,
    {
      calls: number;
      successes: number;
      totalDuration: number;
      lastError?: string;
    }
  > = new Map();
  private evolutionWeights: Map<string, number> = new Map();

  /**
   * ???????????????
   * ????????????????????
   */
  applyEvolutionWeights(weights: Record<string, number>): void {
    for (const [toolName, weight] of Object.entries(weights)) {
      this.evolutionWeights.set(toolName, weight);
    }
    Logger.info(
      `?? ???????: ${Object.keys(weights).join(', ') || '(???)'}`,
      'ToolReliabilityTracker'
    );
  }

  /**
   * ????????????????
   */
  getEvolutionWeights(): Map<string, number> {
    return new Map(this.evolutionWeights);
  }

  /**
   * ?????????????????
   */
  getEvolutionWeight(toolName: string): number {
    return this.evolutionWeights.get(toolName) ?? 1.0;
  }

  /**
   * ?????????? ? ?????
   */
  getCompositeScore(toolName: string): number {
    const successRate = this.getSuccessRate(toolName);
    const weight = this.getEvolutionWeight(toolName);
    return successRate * weight;
  }

  /**
   * ????????
   * @param toolName - ????
   * @param success - ????
   * @param duration - ????(ms)
   * @param error - ????
   */
  recordCall(
    toolName: string,
    success: boolean,
    duration: number,
    error?: string
  ): void {
    const existing = this.stats.get(toolName);
    if (existing) {
      existing.calls++;
      if (success) existing.successes++;
      existing.totalDuration += duration;
      if (error) existing.lastError = error;
    } else {
      this.stats.set(toolName, {
        calls: 1,
        successes: success ? 1 : 0,
        totalDuration: duration,
        lastError: error,
      });
    }
  }

  /**
   * ???????
   * @param toolName - ????
   * @returns ??? (0-1)
   */
  getSuccessRate(toolName: string): number {
    const stat = this.stats.get(toolName);
    if (!stat || stat.calls === 0) return 0;
    return stat.successes / stat.calls;
  }

  /**
   * ??????????
   * @param toolName - ????
   * @returns ????(ms)
   */
  getAverageDuration(toolName: string): number {
    const stat = this.stats.get(toolName);
    if (!stat || stat.calls === 0) return 0;
    return stat.totalDuration / stat.calls;
  }

  /**
   * ??????????????????
   * @param threshold - ????????0.9
   * @returns ?????????
   */
  getUnreliableTools(threshold: number = 0.9): string[] {
    const unreliable: string[] = [];
    for (const [toolName, stat] of this.stats) {
      if (stat.calls > 0 && stat.successes / stat.calls < threshold) {
        unreliable.push(toolName);
      }
    }
    return unreliable;
  }

  /**
   * ??????????
   * @param toolName - ????
   * @returns ?????null
   */
  getStats(
    toolName: string
  ): {
    calls: number;
    successes: number;
    successRate: number;
    avgDuration: number;
    lastError?: string;
  } | null {
    const stat = this.stats.get(toolName);
    if (!stat) return null;
    return {
      calls: stat.calls,
      successes: stat.successes,
      successRate: stat.calls > 0 ? stat.successes / stat.calls : 0,
      avgDuration: stat.calls > 0 ? stat.totalDuration / stat.calls : 0,
      lastError: stat.lastError,
    };
  }

  /**
   * ??????????
   * @returns ??????????
   */
  getAllStats(): Map<
    string,
    {
      calls: number;
      successes: number;
      successRate: number;
      avgDuration: number;
      lastError?: string;
    }
  > {
    const result = new Map<
      string,
      {
        calls: number;
        successes: number;
        successRate: number;
        avgDuration: number;
        lastError?: string;
      }
    >();
    for (const [toolName, stat] of this.stats) {
      result.set(toolName, {
        calls: stat.calls,
        successes: stat.successes,
        successRate: stat.calls > 0 ? stat.successes / stat.calls : 0,
        avgDuration: stat.calls > 0 ? stat.totalDuration / stat.calls : 0,
        lastError: stat.lastError,
      });
    }
    return result;
  }

  /**
   * ????????
   */
  reset(): void {
    this.stats.clear();
  }
}

import { ChildProcess, fork } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import { Logger } from '../utils/Logger';
import { EventBus } from '../shared/EventBus';
import type {
  IntegrationPlatform,
  PlatformConfig,
  IntegrationPlatformInfo,
  IntegrationStatus,
  SendMessageRequest,
  SendMessageResponse,
  IncomingMessageEvent,
} from '../shared/contracts';

interface PendingRequest {
  resolve: (value: unknown) => void;
  reject: (reason: unknown) => void;
  timer: NodeJS.Timeout;
}

export interface GatewayBridgeOptions {
  maxRestartAttempts?: number;
  restartDelayMs?: number;
  requestTimeoutMs?: number;
  healthCheckIntervalMs?: number;
}

const DEFAULT_OPTIONS: Required<GatewayBridgeOptions> = {
  maxRestartAttempts: 5,
  restartDelayMs: 3000,
  requestTimeoutMs: 15000,
  healthCheckIntervalMs: 30000,
};

export class GatewayBridge {
  private worker: ChildProcess | null = null;
  private pendingRequests: Map<string, PendingRequest> = new Map();
  private messageHandler: ((msg: unknown) => void) | null = null;
  private restartAttempts = 0;
  private restartTimer: NodeJS.Timeout | null = null;
  private healthCheckTimer: NodeJS.Timeout | null = null;
  private isShuttingDown = false;
  private workerReady = false;
  private readonly options: Required<GatewayBridgeOptions>;
  private onIncomingMessage:
    | ((message: IncomingMessageEvent) => Promise<void>)
    | null = null;
  private static instance: GatewayBridge | null = null;

  private constructor(options?: GatewayBridgeOptions) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
  }

  static getInstance(options?: GatewayBridgeOptions): GatewayBridge {
    if (!GatewayBridge.instance) {
      GatewayBridge.instance = new GatewayBridge(options);
    }
    return GatewayBridge.instance;
  }

  setIncomingMessageHandler(
    handler: (message: IncomingMessageEvent) => Promise<void>
  ): void {
    this.onIncomingMessage = handler;
  }

  async start(): Promise<void> {
    if (this.worker) {
      Logger.warn('Gateway Worker ????', 'GatewayBridge');
      return;
    }

    this.isShuttingDown = false;
    await this.spawnWorker();
    this.startHealthCheck();
    Logger.info('?? GatewayBridge ?????????????', 'GatewayBridge');
  }

  async stop(): Promise<void> {
    this.isShuttingDown = true;
    this.stopHealthCheck();

    if (this.restartTimer) {
      clearTimeout(this.restartTimer);
      this.restartTimer = null;
    }

    for (const [_id, pending] of this.pendingRequests) {
      clearTimeout(pending.timer);
      pending.reject(new Error('GatewayBridge ????'));
    }
    this.pendingRequests.clear();

    if (this.worker) {
      this.worker.kill('SIGTERM');
      const forceKillTimer = setTimeout(() => {
        if (this.worker) {
          this.worker.kill('SIGKILL');
        }
      }, 5000);

      await new Promise<void>((resolve) => {
        if (this.worker) {
          this.worker.on('exit', () => {
            clearTimeout(forceKillTimer);
            resolve();
          });
        } else {
          resolve();
        }
      });

      this.worker = null;
      this.workerReady = false;
    }

    Logger.info('GatewayBridge ???', 'GatewayBridge');
  }

  isWorkerAlive(): boolean {
    return this.worker !== null && this.workerReady;
  }

  async connectPlatform(
    platform: IntegrationPlatform,
    config: PlatformConfig
  ): Promise<boolean> {
    const result = await this.sendRequest('connect', { platform, config });
    return result as boolean;
  }

  async disconnectPlatform(platform: IntegrationPlatform): Promise<void> {
    await this.sendRequest('disconnect', { platform });
  }

  async sendMessage(request: SendMessageRequest): Promise<SendMessageResponse> {
    return (await this.sendRequest(
      'sendMessage',
      request
    )) as SendMessageResponse;
  }

  getPlatforms(): IntegrationPlatformInfo[] {
    if (!this.isWorkerAlive()) {
      return this.getOfflinePlatforms();
    }

    const syncResult = this.sendSyncRequest('getPlatforms');
    return (
      (syncResult?.data as { platforms: IntegrationPlatformInfo[] })
        ?.platforms ?? this.getOfflinePlatforms()
    );
  }

  getPlatformStatus(
    platform: IntegrationPlatform
  ): IntegrationStatus | undefined {
    if (!this.isWorkerAlive()) {
      return {
        platform,
        connected: false,
        status: 'disconnected',
        error: 'Gateway Worker ???',
      };
    }

    const syncResult = this.sendSyncRequest('getStatus', { platform });
    return syncResult?.data as IntegrationStatus | undefined;
  }

  getWeChatQRState(): {
    qrCodeBase64: string | null;
    status: string;
    botNickname: string | null;
  } | null {
    if (!this.isWorkerAlive()) return null;

    const syncResult = this.sendSyncRequest('getWeChatQRState');
    return syncResult?.data as {
      qrCodeBase64: string | null;
      status: string;
      botNickname: string | null;
    } | null;
  }

  async handleWebhook(
    platform: IntegrationPlatform,
    payload: Record<string, unknown>
  ): Promise<{ success: boolean; response?: unknown }> {
    return (await this.sendRequest('handleWebhook', {
      platform,
      payload,
    })) as { success: boolean; response?: unknown };
  }

  private async spawnWorker(): Promise<void> {
    const jsPath = path.join(__dirname, 'gatewayWorker.js');
    const tsPath = path.join(__dirname, 'gatewayWorker.ts');

    let workerPath: string;
    let execArgv: string[];

    if (fs.existsSync(jsPath)) {
      workerPath = jsPath;
      execArgv = [];
      Logger.info(`?????? Worker: ${jsPath}`, 'GatewayBridge');
    } else if (fs.existsSync(tsPath)) {
      workerPath = tsPath;
      execArgv = ['-r', 'ts-node/register'];
      Logger.info(`???? Worker: ${tsPath}`, 'GatewayBridge');
    } else {
      throw new Error(`??? gatewayWorker ?? (??: ${jsPath}, ${tsPath})`);
    }

    try {
      this.worker = fork(workerPath, [], {
        execArgv,
        env: {
          ...process.env,
          TS_NODE_TRANSPILE_ONLY: 'true',
        },
        stdio: ['pipe', 'pipe', 'pipe', 'ipc'],
      });

      this.worker.stdout?.on('data', (data: Buffer) => {
        const output = data.toString().trim();
        if (output) {
          Logger.debug(`[GW] ${output}`, 'GatewayBridge');
        }
      });

      this.worker.stderr?.on('data', (data: Buffer) => {
        const output = data.toString().trim();
        if (output) {
          Logger.warn(`[GW ERR] ${output}`, 'GatewayBridge');
        }
      });

      this.messageHandler = (msg: unknown) => {
        this.handleWorkerMessage(msg);
      };
      this.worker.on('message', this.messageHandler);

      this.worker.on('exit', (code, signal) => {
        Logger.warn(
          `Gateway Worker ?? (code=${code}, signal=${signal})`,
          'GatewayBridge'
        );
        this.worker = null;
        this.workerReady = false;

        if (!this.isShuttingDown) {
          this.scheduleRestart();
        }
      });

      this.worker.on('error', (err: Error) => {
        Logger.error('Gateway Worker ????', err, 'GatewayBridge');
        this.worker = null;
        this.workerReady = false;

        if (!this.isShuttingDown) {
          this.scheduleRestart();
        }
      });

      await new Promise<void>((resolve, reject) => {
        const readyTimeout = setTimeout(() => {
          this.cleanupWorker();
          reject(new Error('Gateway Worker ???? (10s)'));
        }, 10000);

        const originalHandler = this.messageHandler;
        this.messageHandler = (msg: unknown) => {
          const ipcMsg = msg as { id?: string; data?: { type?: string } };
          if (ipcMsg.id === 'worker_ready' && ipcMsg.data?.type === 'ready') {
            clearTimeout(readyTimeout);
            this.workerReady = true;
            this.restartAttempts = 0;
            Logger.info('? Gateway Worker ???', 'GatewayBridge');
            resolve();

            this.worker?.on('message', originalHandler!);
            this.messageHandler = originalHandler;
            return;
          }
          this.handleWorkerMessage(msg);
        };

        if (this.worker) {
          this.worker.off('message', originalHandler!);
          this.worker.on('message', this.messageHandler);
        }
      });
    } catch (error) {
      Logger.error(
        'Gateway Worker ????????????',
        error as Error,
        'GatewayBridge'
      );
      this.cleanupWorker();
      throw error;
    }
  }

  private cleanupWorker(): void {
    if (this.worker) {
      this.worker.kill('SIGTERM');
      this.worker = null;
    }
    this.workerReady = false;
  }

  private handleWorkerMessage(msg: unknown): void {
    const ipcMsg = msg as {
      id: string;
      success: boolean;
      data?: unknown;
      error?: string;
    };

    if (!ipcMsg.id) return;

    const pending = this.pendingRequests.get(ipcMsg.id);
    if (pending) {
      clearTimeout(pending.timer);
      this.pendingRequests.delete(ipcMsg.id);

      if (ipcMsg.success) {
        pending.resolve(ipcMsg.data);
      } else {
        pending.reject(new Error(ipcMsg.error || 'Gateway Worker ????'));
      }
      return;
    }

    if (
      ipcMsg.data &&
      typeof ipcMsg.data === 'object' &&
      (ipcMsg.data as { type?: string }).type === 'incoming_message'
    ) {
      const payload = (ipcMsg.data as { payload: IncomingMessageEvent })
        .payload;
      if (this.onIncomingMessage && payload) {
        this.onIncomingMessage(payload).catch((err: Error) => {
          Logger.error('????????', err, 'GatewayBridge');
        });
      }

      EventBus.emit('integration_message', {
        platform: payload.platform,
        type: payload.type,
        content: payload.content,
        from: payload.from,
        fromName: payload.fromName,
        timestamp: payload.timestamp || new Date().toISOString(),
        rawData: payload.rawData,
      });
      return;
    }

    if (ipcMsg.id?.startsWith('err_')) {
      Logger.error(
        `Gateway Worker ??: ${ipcMsg.error}`,
        undefined,
        'GatewayBridge'
      );
    }
  }

  private sendRequest(type: string, payload?: unknown): Promise<unknown> {
    return new Promise((resolve, reject) => {
      if (!this.worker || !this.workerReady) {
        reject(new Error('Gateway Worker ???'));
        return;
      }

      const id = `req_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
      const timer = setTimeout(() => {
        this.pendingRequests.delete(id);
        reject(new Error(`????: ${type}`));
      }, this.options.requestTimeoutMs);

      this.pendingRequests.set(id, { resolve, reject, timer });

      this.worker.send!({ id, type, payload });
    });
  }

  private sendSyncRequest(
    type: string,
    payload?: unknown
  ): { data?: unknown } | null {
    if (!this.worker || !this.workerReady) return null;

    let result: { data?: unknown } | null = null;
    const id = `sync_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

    const tempHandler = (msg: unknown) => {
      const ipcMsg = msg as { id?: string; data?: unknown };
      if (ipcMsg.id === id) {
        result = { data: ipcMsg.data };
      }
    };

    this.worker.on('message', tempHandler);
    this.worker.send!({ id, type, payload });

    const deadline = Date.now() + 5000;
    while (!result && Date.now() < deadline) {
      continue;
    }

    this.worker.off('message', tempHandler);
    return result;
  }

  private scheduleRestart(): void {
    if (this.isShuttingDown) return;

    if (this.restartAttempts >= this.options.maxRestartAttempts) {
      Logger.error(
        `Gateway Worker ???????? (${this.options.maxRestartAttempts})?????`,
        undefined,
        'GatewayBridge'
      );

      EventBus.emit('system_status', 'gateway_down', '???????????');
      return;
    }

    this.restartAttempts++;
    const delay = Math.min(
      this.options.restartDelayMs * Math.pow(1.5, this.restartAttempts - 1),
      60000
    );

    Logger.info(
      `Gateway Worker ?? ${Math.round(delay / 1000)}s ??? (? ${this.restartAttempts} ?)`,
      'GatewayBridge'
    );

    this.restartTimer = setTimeout(async () => {
      try {
        await this.spawnWorker();
        Logger.info('? Gateway Worker ????', 'GatewayBridge');
      } catch {
        Logger.warn('Gateway Worker ??????????', 'GatewayBridge');
        this.scheduleRestart();
      }
    }, delay);
  }

  private startHealthCheck(): void {
    this.healthCheckTimer = setInterval(async () => {
      if (!this.worker || !this.workerReady) return;

      try {
        await this.sendRequest('ping');
      } catch {
        Logger.warn('Gateway Worker ??????', 'GatewayBridge');
      }
    }, this.options.healthCheckIntervalMs);
  }

  private stopHealthCheck(): void {
    if (this.healthCheckTimer) {
      clearInterval(this.healthCheckTimer);
      this.healthCheckTimer = null;
    }
  }

  private getOfflinePlatforms(): IntegrationPlatformInfo[] {
    const PLATFORM_INFO: Record<
      IntegrationPlatform,
      Omit<IntegrationPlatformInfo, 'status' | 'available'>
    > = {
      wechat: {
        id: 'wechat',
        name: '??',
        icon: '??',
        description: '???????? / ???/???',
        enabled: true,
      },
      feishu: {
        id: 'feishu',
        name: '??',
        icon: '??',
        description: '???????',
        enabled: true,
      },
      dingtalk: {
        id: 'dingtalk',
        name: '??',
        icon: '??',
        description: '???????',
        enabled: true,
      },
      qq: {
        id: 'qq',
        name: 'QQ',
        icon: '??',
        description: '?? Mirai ?? QQ ???',
        enabled: true,
      },
    };

    return Object.entries(PLATFORM_INFO).map(([key, info]) => ({
      ...info,
      available: false,
      status: {
        platform: key as IntegrationPlatform,
        connected: false,
        status: 'disconnected' as const,
        error: 'Gateway Worker ???',
      },
    }));
  }
