      await this.captureQRCode();
      this.loginState.status = 'waiting_scan';
    } catch {
      // ????????????
    }
  }

  private startLoginMonitor(): void {
    this.loginCheckTimer = setInterval(async () => {
      if (!this.page) return;

      try {
        // ???????
        const isLoggedIn = await this.page.evaluate(() => {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const win = window as any;
          return (
            typeof win.login !== 'undefined' ||
            document.querySelector('.chat') !== null ||
            document.querySelector('#chatArea') !== null
          );
        });

        if (isLoggedIn) {
          this.loginState.status = 'logged_in';

          // ??????
          const userInfo = await this.page.evaluate(() => {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const win = window as any;
            return {
              wxid: win.__wxUser?.uin || win.uin || 'unknown',
              nickname:
                win.__wxUser?.nickName ||
                document.querySelector('.avatar_text')?.textContent ||
                'WeChat User',
            };
          });

          this.loginState.botWxid = userInfo.wxid;
          this.loginState.botNickname = userInfo.nickname;

          this.updateStatus('connected');
          Logger.info(`?????: ${userInfo.nickname}`, 'WeChatQRAdapter');

          if (this.loginCheckTimer) {
            clearInterval(this.loginCheckTimer);
            this.loginCheckTimer = null;
          }
        }
      } catch {
        // ???????
      }
    }, 2000);

    // ???? 5 ??????
    setTimeout(
      () => {
        if (this.loginState.status === 'waiting_scan') {
          void this.refreshQRCode();
        }
      },
      5 * 60 * 1000
    );
  }

  private startMessagePolling(): void {
    this.messagePollTimer = setInterval(async () => {
      if (this.loginState.status !== 'logged_in' || !this.page) return;

      try {
        const messages = await this.page.evaluate(() => {
          const win = window as any;
          // ?????
          if (win.__newMessages && win.__newMessages.length > 0) {
            const msgs = win.__newMessages;
            win.__newMessages = [];
            return msgs;
          }
          return [];
        });

        if (Array.isArray(messages)) {
          for (const msg of messages) {
            const incoming: IncomingMessageEvent = {
              platform: 'wechat',
              type: msg.type === 'image' ? 'image' : 'text',
              content: msg.content || '',
              from: msg.from || msg.from_wxid,
              fromName: msg.from_name || msg.from_nickname,
              timestamp: new Date().toISOString(),
              rawData: msg,
            };
            await this.emitMessage(incoming);
          }
        }
      } catch {
        // ???????
      }
    }, 1500);
  }

  private async cleanup(): Promise<void> {
    if (this.loginCheckTimer) {
      clearInterval(this.loginCheckTimer);
      this.loginCheckTimer = null;
    }
    if (this.messagePollTimer) {
      clearInterval(this.messagePollTimer);
      this.messagePollTimer = null;
    }
    if (this.page) {
      try {
        await this.page.close();
      } catch {}
      this.page = null;
    }
    if (this.browser) {
      try {
        await this.browser.close();
      } catch {}
      this.browser = null;
    }
  }
}

import { IntegrationManager } from './IntegrationManager';
import { Logger } from '../utils/Logger';
import { EventBus } from '../shared/EventBus';
import type {
  IntegrationPlatform,
  PlatformConfig,
  IncomingMessageEvent,
} from '../shared/contracts';

interface IpcMessage {
  id: string;
  type: string;
  payload?: unknown;
}

interface IpcResponse {
  id: string;
  success: boolean;
  data?: unknown;
  error?: string;
}

const im = IntegrationManager.getInstance();

function send(msg: IpcResponse): void {
  if (process.send) {
    process.send(msg);
  }
}

function handleMessage(msg: IpcMessage): void {
  switch (msg.type) {
    case 'connect': {
      const { platform, config } = msg.payload as {
        platform: IntegrationPlatform;
        config: PlatformConfig;
      };
      im.connectPlatform(platform, config)
        .then((success) => {
          send({
            id: msg.id,
            success,
            data: { platform, status: success ? 'connected' : 'failed' },
          });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'disconnect': {
      const { platform: dp } = msg.payload as { platform: IntegrationPlatform };
      im.disconnectPlatform(dp)
        .then(() => {
          send({ id: msg.id, success: true, data: { platform: dp } });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'sendMessage': {
      const req = msg.payload as {
        platform: IntegrationPlatform;
        message: string;
        to?: string;
        imageUrls?: string[];
        mentions?: string[];
      };
      im.sendMessage(req)
        .then((result) => {
          send({ id: msg.id, success: result.success, data: result });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'getPlatforms': {
      const platforms = im.getPlatforms();
      send({ id: msg.id, success: true, data: { platforms } });
      break;
    }
    case 'getStatus': {
      const { platform: sp } = msg.payload as { platform: IntegrationPlatform };
      const status = im.getPlatformStatus(sp);
      send({ id: msg.id, success: true, data: status });
      break;
    }
    case 'getWeChatQRState': {
      const qrState = im.getWeChatQRState();
      send({ id: msg.id, success: true, data: qrState });
      break;
    }
    case 'handleWebhook': {
      const { platform: wp, payload: wPayload } = msg.payload as {
        platform: IntegrationPlatform;
        payload: Record<string, unknown>;
      };
      im.handleWebhook(wp, wPayload)
        .then((result) => {
          send({ id: msg.id, success: result.success, data: result });
        })
        .catch((err: Error) => {
          send({ id: msg.id, success: false, error: err.message });
        });
      break;
    }
    case 'ping': {
      send({
        id: msg.id,
        success: true,
        data: { status: 'alive', pid: process.pid },
      });
      break;
    }
    default:
      send({
        id: msg.id,
        success: false,
        error: `Unknown message type: ${msg.type}`,
      });
  }
}

