          score -= 30;
        } else if (failureRate > 0.2) {
          issues.push(`???????: ${(failureRate * 100).toFixed(1)}%`);
          score -= 15;
        }
      }
    } catch {
      issues.push('?????????');
      score -= 30;
    }

    try {
      const securityStats = perf.getCategoryStats('security');
      if (securityStats.totalCalls > 0 && securityStats.errorRate > 0.3) {
        issues.push(
          `?????????: ${(securityStats.errorRate * 100).toFixed(1)}%`
        );
        score -= 20;
      }
    } catch {
      issues.push('?????????');
      score -= 10;
    }

    try {
      this.encryptionManager.encrypt('healthcheck');
    } catch {
      issues.push('???????');
      score -= 40;
    }

    if (this.emergencyMode) {
      issues.push('????????');
      score -= 25;
    }

    if (!this.initialized) {
      issues.push('?????????');
      score -= 50;
    }

    score = Math.max(0, Math.min(100, score));

    return {
      healthy: score >= 60,
      score,
      issues,
    };
  }

  public async secureExecuteOperation(
    userId: string,
    operation: string,
    resource: string,
    action: string,
    parameters: Record<string, unknown>,
    ipAddress: string,
    deviceId: string
  ): Promise<{ success: boolean; result: unknown; error?: string }> {
    this.ensureInitialized();
    if (this.emergencyMode)
      return { success: false, result: null, error: '????????' };
    const redlineCheck = this.policyEngine.checkSecurityRedlines(
      `${operation} ${action} ${JSON.stringify(parameters)}`
    );
    if (redlineCheck.violation) {
      this.recordSecurityEvent({
        type: 'unauthorized',
        severity: 'critical',
        message: `??????: ${redlineCheck.reasons.join(', ')}`,
        userId,
        ipAddress,
        actionTaken: '????',
      });
      return { success: false, result: null, error: '????????' };
    }
    this.recordAudit({
      userId,
      operation,
      resource,
      action,
      parameters,
      result: 'pending',
      ipAddress,
      deviceId,
      status: 'pending',
    });
    return { success: true, result: { success: true, data: '??????' } };
  }
}

