import express from 'express';
import { UserProfile } from '../../memory/UserProfile';

import { JiabaixingCore } from '../../core/JiabaixingCore';
import { Logger } from '../../utils/Logger';

export function registerMemoryRoutes(
  app: express.Application,
  core: JiabaixingCore | null
): void {
  app.post(
    '/api/memory/store',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const {
          content,
          userId,
          importance,
          tags: _tags,
          emotion: _emotion,
          scene,
        } = req.body as {
          content?: string;
          userId?: string;
          importance?: string;
          tags?: string[];
          emotion?: unknown;
          scene?: unknown;
        };

        if (!content) {
          return res
            .status(400)
            .json({ success: false, error: '??content??' });
        }

        if (!core) {
          return res
            .status(503)
            .json({ success: false, error: '????????' });
        }

        const memoryEngine = core.getMemoryEngine();
        if (!memoryEngine) {
          return res
            .status(503)
            .json({ success: false, error: '????????' });
        }

        if (memoryEngine.storeShortTermMemory) {
          await memoryEngine.storeShortTermMemory(
            content,
            (scene as string) || 'general',
            userId
          );
        }

        res.json({
          success: true,
          data: {
            id: Date.now().toString(),
            content,
            timestamp: new Date().toISOString(),
            importance: importance || 'medium',
          },
        });
      } catch (error) {
        Logger.error('? ??????', error as Error, 'MemoryAPI');
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );

  app.get('/api/memory/search', async (req, res) => {
    try {
      const {
        query,
        userId,
        limit = 10,
      } = req.query as {
        query?: string;
        userId?: string;
        limit?: string;
      };

      if (!query) {
        return res.status(400).json({ success: false, error: '??query??' });
      }

      if (!core) {
        return res
          .status(503)
          .json({ success: false, error: '????????' });
      }

      const memoryEngine = core.getMemoryEngine();
      if (!memoryEngine) {
        return res
          .status(503)
          .json({ success: false, error: '????????' });
      }

      let results: unknown[] = [];
      if (memoryEngine.retrieveContext) {
        const context = await memoryEngine.retrieveContext(query, userId);
        results = context.memories.map((m: unknown, index: number) => {
          const mem = m as Record<string, unknown>;
          const relevance = mem.relevance as number;
          return {
            id: `memory_${index}`,
            content: mem.content,
            importance:
              relevance > 0.7 ? 'high' : relevance > 0.4 ? 'medium' : 'low',
            timestamp: new Date().toISOString(),
            similarity: relevance,
          };
        });
      }

      res.json({
        success: true,
        data: {
          query,
          results: results.slice(0, parseInt(limit as string) || 10),
          total: results.length,
        },
      });
    } catch (error) {
      Logger.error('? ??????', error as Error, 'MemoryAPI');
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.get('/api/memory/profile', async (req, res) => {
    try {
      const { userId: _userId } = req.query as { userId?: string };

      if (!core) {
        return res
          .status(503)
          .json({ success: false, error: '????????' });
      }

      const memoryEngine = core.getMemoryEngine();
      if (!memoryEngine) {
        return res
          .status(503)
          .json({ success: false, error: '????????' });
      }

      const userProfile = memoryEngine.getUserProfile?.() as
        | UserProfile
        | undefined;

      if (!userProfile) {
        return res
          .status(404)
          .json({ success: false, error: '???????' });
      }

      res.json({
        success: true,
        data: {
          basicInfo: userProfile.getBasicInfo(),
          developmentHabits: userProfile.getDevelopmentHabits(),
          lifePreferences: userProfile.getLifePreferences(),
          emotionalPatterns: userProfile.getEmotionalPatterns(),
          taskPreferences: userProfile.getTaskPreferences(),
        },
      });
    } catch (error) {
      Logger.error('? ????????', error as Error, 'MemoryAPI');
      res.status(500).json({ success: false, error: (error as Error).message });
    }
  });

  app.post(
    '/api/memory/preferences',
    express.json({ limit: '1mb' }),
    async (req, res) => {
      try {
        const { preferences } = req.body as {
          preferences?: Record<string, unknown>;
        };

        if (!preferences) {
          return res
            .status(400)
            .json({ success: false, error: '??preferences??' });
        }

        if (!core) {
          return res
            .status(503)
            .json({ success: false, error: '????????' });
        }

        const memoryEngine = core.getMemoryEngine();
        if (!memoryEngine) {
          return res
            .status(503)
            .json({ success: false, error: '????????' });
        }

        const userProfile = memoryEngine.getUserProfile?.() as
          | UserProfile
          | undefined;

        if (!userProfile) {
          return res
            .status(404)
            .json({ success: false, error: '???????' });
        }

        await userProfile.update({
          ...preferences,
          timestamp: new Date(),
        });

        res.json({
          success: true,
          data: {
            basicInfo: userProfile.getBasicInfo(),
            developmentHabits: userProfile.getDevelopmentHabits(),
            lifePreferences: userProfile.getLifePreferences(),
            emotionalPatterns: userProfile.getEmotionalPatterns(),
            taskPreferences: userProfile.getTaskPreferences(),
          },
        });
      } catch (error) {
        Logger.error('? ????????', error as Error, 'MemoryAPI');
        res
          .status(500)
          .json({ success: false, error: (error as Error).message });
      }
    }
  );
}

/**
 * Performance Monitor - ??????
 * ????????????????????
 */

import { Logger } from './Logger';

export interface PerformanceMetric {
  id: string;
  name: string;
  category: string;
  startTime: number;
  endTime?: number;
  duration?: number;
  success: boolean;
  metadata?: Record<string, any>;
}

export interface PerformanceStats {
  totalCalls: number;
  successCount: number;
  failureCount: number;
  avgDuration: number;
  minDuration: number;
  maxDuration: number;
  p50Duration: number;
  p95Duration: number;
  p99Duration: number;
  recentMetrics: PerformanceMetric[];
  errorRate: number;
  throughput: number; // calls per second
}

export interface PerformanceReport {
  timestamp: number;
  totalMetrics: number;
  categories: Record<string, PerformanceStats>;
  topSlowest: Array<{ name: string; avgDuration: number; calls: number }>;
  topErrors: Array<{ name: string; errorRate: number; failures: number }>;
  systemLoad: {
    memoryUsage: NodeJS.MemoryUsage;
    uptime: number;
  };
}

export class PerformanceMonitor {
  private static instance: PerformanceMonitor;
  private metrics: Map<string, PerformanceMetric[]>;
  private activeSpans: Map<string, PerformanceMetric>;
  private maxMetricsPerCategory: number = 1000;
  private startTime: number;

  private constructor() {
    this.metrics = new Map();
    this.activeSpans = new Map();
    this.startTime = Date.now();
    Logger.info('?? ?????????', 'PerformanceMonitor');
  }

  /**
   * ??????
   */
  public static getInstance(): PerformanceMonitor {
    if (!PerformanceMonitor.instance) {
      PerformanceMonitor.instance = new PerformanceMonitor();
    }
    return PerformanceMonitor.instance;
  }

  /**
   * ??????
   */
  public startSpan(
    name: string,
    category: string = 'default',
    metadata?: Record<string, any>
  ): string {
    const id = `${name}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const span: PerformanceMetric = {
      id,
      name,
      category,
      startTime: Date.now(),
      success: true,
      metadata,
    };
    this.activeSpans.set(id, span);
    Logger.debug(`?? ????: ${name} (${id})`, 'PerformanceMonitor');
    return id;
  }

  /**
   * ??????
   */
  public endSpan(
    id: string,
    success: boolean = true,
    metadata?: Record<string, any>
  ): PerformanceMetric | null {
    const span = this.activeSpans.get(id);
    if (!span) {
      Logger.warn(`?? ????????span: ${id}`, 'PerformanceMonitor');
      return null;
    }

    const endTime = Date.now();
    const duration = endTime - span.startTime;

    const completedSpan: PerformanceMetric = {
      ...span,
      endTime,
      duration,
      success,
      metadata: { ...span.metadata, ...metadata },
    };

    this.activeSpans.delete(id);
    this.recordMetric(completedSpan);

    Logger.debug(
      `?? ????: ${span.name} - ${duration}ms ${success ? '?' : '?'}`,
      'PerformanceMonitor'
    );
    return completedSpan;
  }

  /**
   * ????????????
   */
  public recordMetric(metric: PerformanceMetric): void {
    const category = metric.category || 'default';
    if (!this.metrics.has(category)) {
      this.metrics.set(category, []);
    }

    const categoryMetrics = this.metrics.get(category)!;
    categoryMetrics.push(metric);

    // ???????????
    if (categoryMetrics.length > this.maxMetricsPerCategory) {
      categoryMetrics.shift();
    }
  }

  /**
   * ?????????
   */
  public async measure<T>(
    name: string,
    fn: () => Promise<T>,
    category: string = 'default',
    metadata?: Record<string, any>
  ): Promise<T> {
    const id = this.startSpan(name, category, metadata);
    try {
      const result = await fn();
      this.endSpan(id, true);
      return result;
    } catch (error) {
      this.endSpan(id, false, { error: (error as Error).message });
      throw error;
    }
  }

  /**
   * ???????
   */
  public measureSync<T>(
    name: string,
    fn: () => T,
    category: string = 'default',
    metadata?: Record<string, any>
  ): T {
    const id = this.startSpan(name, category, metadata);
    try {
      const result = fn();
      this.endSpan(id, true);
      return result;
    } catch (error) {
      this.endSpan(id, false, { error: (error as Error).message });
      throw error;
    }
  }

  /**
   * ??????
   */
  public getCategoryStats(category: string): PerformanceStats {
    const metrics = this.metrics.get(category) || [];
    return this.calculateStats(metrics);
  }

  /**
   * ??????
   */
  private calculateStats(metrics: PerformanceMetric[]): PerformanceStats {
    if (metrics.length === 0) {
      return {
        totalCalls: 0,
        successCount: 0,
        failureCount: 0,
        avgDuration: 0,
        minDuration: 0,
        maxDuration: 0,
        p50Duration: 0,
        p95Duration: 0,
        p99Duration: 0,
        recentMetrics: [],
        errorRate: 0,
        throughput: 0,
      };
    }

    const durations = metrics
      .filter((m) => m.duration !== undefined)
      .map((m) => m.duration!)
      .sort((a, b) => a - b);

    const totalCalls = metrics.length;
    const successCount = metrics.filter((m) => m.success).length;
    const failureCount = totalCalls - successCount;
    const totalDuration = durations.reduce((sum, d) => sum + d, 0);
    const avgDuration = totalDuration / durations.length;

    const uptimeSeconds = (Date.now() - this.startTime) / 1000;
    const throughput = totalCalls / uptimeSeconds;

    return {
      totalCalls,
      successCount,
      failureCount,
      avgDuration,
      minDuration: durations[0],
      maxDuration: durations[durations.length - 1],
      p50Duration: this.getPercentile(durations, 50),
      p95Duration: this.getPercentile(durations, 95),
      p99Duration: this.getPercentile(durations, 99),
      recentMetrics: metrics.slice(-50),
      errorRate: totalCalls > 0 ? failureCount / totalCalls : 0,
      throughput,
    };
  }

  /**
   * ??????
   */
  private getPercentile(sortedArray: number[], percentile: number): number {
    if (sortedArray.length === 0) return 0;
    const index = Math.ceil((percentile / 100) * sortedArray.length) - 1;
    return sortedArray[Math.max(0, Math.min(index, sortedArray.length - 1))];
  }

  /**
   * ????????
   */
  public getReport(): PerformanceReport {
    const categories: Record<string, PerformanceStats> = {};

    for (const [category, metrics] of this.metrics.entries()) {
      categories[category] = this.calculateStats(metrics);
    }

    // ???????
    const allMetricNames = new Set<string>();
    for (const metrics of this.metrics.values()) {
      for (const metric of metrics) {
        allMetricNames.add(metric.name);
      }
    }

    const topSlowest: Array<{
      name: string;
      avgDuration: number;
      calls: number;
    }> = [];
    for (const name of allMetricNames) {
      const nameMetrics = [...this.metrics.values()]
        .flat()
        .filter((m) => m.name === name && m.duration !== undefined);

      if (nameMetrics.length > 0) {
        const avgDuration =
          nameMetrics.reduce((sum, m) => sum + m.duration!, 0) /
          nameMetrics.length;
        topSlowest.push({ name, avgDuration, calls: nameMetrics.length });
      }
    }
    topSlowest.sort((a, b) => b.avgDuration - a.avgDuration);

    // ??????????
    const topErrors: Array<{
      name: string;
      errorRate: number;
      failures: number;
    }> = [];
    for (const name of allMetricNames) {
      const nameMetrics = [...this.metrics.values()]
        .flat()
        .filter((m) => m.name === name);
      const failures = nameMetrics.filter((m) => !m.success).length;
      const errorRate =
        nameMetrics.length > 0 ? failures / nameMetrics.length : 0;
      if (failures > 0) {
        topErrors.push({ name, errorRate, failures });
      }
    }
    topErrors.sort((a, b) => b.errorRate - a.errorRate);

    return {
      timestamp: Date.now(),
      totalMetrics: [...this.metrics.values()].flat().length,
      categories,
      topSlowest: topSlowest.slice(0, 10),
      topErrors: topErrors.slice(0, 10),
      systemLoad: {
        memoryUsage: process.memoryUsage(),
        uptime: process.uptime(),
      },
    };
  }

  /**
   * ??????
   */
  public printReport(): void {
    const report = this.getReport();

    Logger.info('='.repeat(60), 'PerformanceMonitor');
    Logger.info('?? ??????', 'PerformanceMonitor');
    Logger.info(
      `?? ????: ${new Date(report.timestamp).toISOString()}`,
      'PerformanceMonitor'
    );
    Logger.info(`?? ????: ${report.totalMetrics}`, 'PerformanceMonitor');
    Logger.info('', 'PerformanceMonitor');

    // ????
    for (const [category, stats] of Object.entries(report.categories)) {
      Logger.info(`?? ${category}:`, 'PerformanceMonitor');
      Logger.info(`   ????: ${stats.totalCalls}`, 'PerformanceMonitor');
      Logger.info(
        `   ???: ${((stats.successCount / stats.totalCalls) * 100).toFixed(1)}%`,
        'PerformanceMonitor'
      );
      Logger.info(
        `   ????: ${stats.avgDuration.toFixed(2)}ms`,
        'PerformanceMonitor'
      );
      Logger.info(
        `   P50/P95/P99: ${stats.p50Duration.toFixed(2)}/${stats.p95Duration.toFixed(2)}/${stats.p99Duration.toFixed(2)}ms`,
        'PerformanceMonitor'
      );
    }

    // ????
    if (report.topSlowest.length > 0) {
      Logger.info('', 'PerformanceMonitor');
      Logger.info('?? ???? TOP 10:', 'PerformanceMonitor');
      for (let i = 0; i < Math.min(10, report.topSlowest.length); i++) {
        const item = report.topSlowest[i];
        Logger.info(
          `   ${i + 1}. ${item.name}: ${item.avgDuration.toFixed(2)}ms (${item.calls} calls)`,
          'PerformanceMonitor'
        );
      }
    }

    // ????
    if (report.topErrors.length > 0) {
      Logger.info('', 'PerformanceMonitor');
      Logger.info('?? ????????:', 'PerformanceMonitor');
      for (let i = 0; i < Math.min(10, report.topErrors.length); i++) {
        const item = report.topErrors[i];
        Logger.info(
          `   ${i + 1}. ${item.name}: ${(item.errorRate * 100).toFixed(1)}% (${item.failures} failures)`,
          'PerformanceMonitor'
        );
      }
    }

    // ????
    Logger.info('', 'PerformanceMonitor');
    Logger.info('?? ????:', 'PerformanceMonitor');
    Logger.info(
      `   RSS: ${(report.systemLoad.memoryUsage.rss / 1024 / 1024).toFixed(2)} MB`,
      'PerformanceMonitor'
    );
    Logger.info(
      `   Heap Total: ${(report.systemLoad.memoryUsage.heapTotal / 1024 / 1024).toFixed(2)} MB`,
      'PerformanceMonitor'
    );
    Logger.info(
      `   Heap Used: ${(report.systemLoad.memoryUsage.heapUsed / 1024 / 1024).toFixed(2)} MB`,
      'PerformanceMonitor'
    );
    Logger.info(
      `   Uptime: ${report.systemLoad.uptime.toFixed(1)}s`,
      'PerformanceMonitor'
    );
    Logger.info('='.repeat(60), 'PerformanceMonitor');
  }

  /**
   * ??????
   */
  public clear(): void {
    this.metrics.clear();
    this.activeSpans.clear();
    Logger.info('?? ?????????', 'PerformanceMonitor');
  }

  /**
   * ?????????
   */
  public getMetricStats(name: string): PerformanceStats {
    const metrics = [...this.metrics.values()]
      .flat()
      .filter((m) => m.name === name);
    return this.calculateStats(metrics);
  }
}

